create table if not exists public.user_location_sessions (id uuid primary key default gen_random_uuid(),user_id uuid null references auth.users(id) on delete cascade,latitude double precision not null,longitude double precision not null,accuracy_meters double precision,radius_meters integer not null default 16093,tier_code text,discovered_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb);
create index if not exists user_location_sessions_coords_idx on public.user_location_sessions(latitude,longitude);
create or replace function public.prepare_universal_location_discovery(p_lat double precision,p_lng double precision,p_radius_m integer default 16093,p_user_id uuid default auth.uid()) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_radius integer:=greatest(1000,least(coalesce(p_radius_m,16093),50000)); v_tier text; v_session uuid; v_locations jsonb; v_lat_delta double precision; v_lng_delta double precision; begin if p_lat is null or p_lng is null or p_lat < -90 or p_lat > 90 or p_lng < -180 or p_lng > 180 then raise exception 'valid coordinates required'; end if; select subscription_tier::text into v_tier from profiles where id=p_user_id; insert into user_location_sessions(user_id,latitude,longitude,radius_meters,tier_code) values(p_user_id,p_lat,p_lng,v_radius,v_tier) returning id into v_session; v_lat_delta:=v_radius/111320.0; v_lng_delta:=v_radius/(111320.0*greatest(cos(radians(p_lat)),0.1)); select coalesce(jsonb_agg(to_jsonb(x) order by x.distance_meters),'[]'::jsonb) into v_locations from (select l.id,l.name,l.address,l.city,l.state,l.postal_code,l.latitude,l.longitude,l.place_type,l.source,l.source_dataset,l.source_external_id,l.source_metadata,l.verification_status,l.bathroom_verification_status,l.accessible,l.changing_table,l.cleanliness,l.cleanliness_pct,l.rating,l.review_count,l.updated_at,round((6371000*2*asin(sqrt(power(sin(radians(l.latitude-p_lat)/2),2)+cos(radians(p_lat))*cos(radians(l.latitude))*power(sin(radians(l.longitude-p_lng)/2),2))))::numeric,1) distance_meters from locations l where l.is_active=true and l.latitude between p_lat-v_lat_delta and p_lat+v_lat_delta and l.longitude between p_lng-v_lng_delta and p_lng+v_lng_delta order by distance_meters limit 1000) x where x.distance_meters<=v_radius; update user_location_sessions set last_seen_at=now(),metadata=jsonb_build_object('location_count',jsonb_array_length(v_locations)) where id=v_session; return jsonb_build_object('session_id',v_session,'tier',coalesce(v_tier,'free'),'radius_meters',v_radius,'locations',v_locations,'needs_external_discovery',jsonb_array_length(v_locations)=0,'data_policy','universal_discovery_v1'); end $$;
revoke all on function public.prepare_universal_location_discovery(double precision,double precision,integer,uuid) from public; grant execute on function public.prepare_universal_location_discovery(double precision,double precision,integer,uuid) to authenticated;
